:root {
  --color-bg: #1e1e2f;
  --color-surface: #2a2a40;
  --color-primary: #f9c74f;
  --color-secondary: #90be6d;
  --color-accent: #f94144;
  --color-text: #ffffff;
  --color-card-back: #3a3a5c;
  --color-card-back-hover: #4a4a6c;
  --font-base: 18px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-base);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  max-width: 600px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 16px;
  color: var(--color-primary);
}

.stats {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  gap: 16px;
}

#move-counter {
  font-weight: bold;
  color: var(--color-secondary);
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background-color: var(--color-primary);
  color: #1e1e2f;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  font-weight: bold;
}

button:hover {
  background-color: #ffd966;
}

button:focus-visible {
  outline: 3px solid var(--color-secondary);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 16px;
}

.card {
  aspect-ratio: 1;
  border-radius: 12px;
  background-color: var(--color-card-back);
  cursor: pointer;
  transition: background-color 0.2s, transform 0.2s;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: bold;
  color: transparent;
  user-select: none;
}

.card:hover {
  background-color: var(--color-card-back-hover);
}

.card:focus-visible {
  outline: 3px solid var(--color-secondary);
  outline-offset: 2px;
}

.card:active {
  transform: scale(0.95);
}

.card.flipped {
  background-color: var(--color-surface);
  color: var(--color-text);
}

.card.matched {
  background-color: var(--color-secondary);
  color: #1e1e2f;
  cursor: default;
}

.card.matched:hover {
  background-color: var(--color-secondary);
}

.card.matched:active {
  transform: none;
}

.win-message {
  min-height: 1.5em;
  margin-top: 16px;
  font-size: 1.2rem;
  color: var(--color-primary);
  font-weight: bold;
}

@media (max-width: 480px) {
  .game-board {
    gap: 8px;
  }
  h1 {
    font-size: 1.4rem;
  }
  button {
    padding: 10px 16px;
    font-size: 0.9rem;
  }
}

const COLORS = [
  '#f94144', '#f3722c', '#f8961e', '#f9c74f',
  '#90be6d', '#43aa8b', '#577590', '#9b5de5'
];

const board = document.getElementById('game-board');
const moveCounter = document.getElementById('move-counter');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game-btn');

let cards = [];
let flippedCards = [];
let moves = 0;
let matchedPairs = 0;
let lockBoard = false;

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function createBoard() {
  board.innerHTML = '';
  cards = [];
  flippedCards = [];
  moves = 0;
  matchedPairs = 0;
  lockBoard = false;
  moveCounter.textContent = '0';
  winMessage.textContent = '';

  const deck = shuffle([...COLORS, ...COLORS]);

  deck.forEach((color, index) => {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.color = color;
    card.dataset.index = index;
    card.setAttribute('aria-label', 'Hidden card');
    card.addEventListener('click', handleCardClick);
    board.appendChild(card);
    cards.push(card);
  });
}

function handleCardClick(event) {
  const card = event.currentTarget;
  if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
    return;
  }

  flipCard(card);
  flippedCards.push(card);

  if (flippedCards.length === 2) {
    moves++;
    moveCounter.textContent = moves;
    checkMatch();
  }
}

function flipCard(card) {
  card.classList.add('flipped');
  card.style.backgroundColor = card.dataset.color;
  card.setAttribute('aria-label', 'Card revealed');
}

function unflipCard(card) {
  card.classList.remove('flipped');
  card.style.backgroundColor = '';
  card.setAttribute('aria-label', 'Hidden card');
}

function checkMatch() {
  const [first, second] = flippedCards;
  if (first.dataset.color === second.dataset.color) {
    first.classList.add('matched');
    second.classList.add('matched');
    first.setAttribute('aria-label', 'Matched card');
    second.setAttribute('aria-label', 'Matched card');
    first.disabled = true;
    second.disabled = true;
    flippedCards = [];
    matchedPairs++;
    if (matchedPairs === COLORS.length) {
      winMessage.textContent = `You won in ${moves} moves!`;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      unflipCard(first);
      unflipCard(second);
      flippedCards = [];
      lockBoard = false;
    }, 800);
  }
}

newGameBtn.addEventListener('click', createBoard);

createBoard();
